<section class="admin-v2-page-intro"><div><a href="/admin-v2/team">← العودة إلى الفريق</a><span class="admin-v2-eyebrow">PER-USER ACCESS</span><h2>تخصيص الصلاحيات</h2><p><?=e($member['name'])?> · <?=e($member['username'])?> — المنح والمنع الفردي يتغلب على صلاحيات الدور.</p></div></section>
<form method="post" action="/admin-v2/team/permissions" class="admin-v2-panel"><input type="hidden" name="_token" value="<?=e(App\Core\Csrf::token())?>"><input type="hidden" name="user_id" value="<?=e($member['id'])?>"><div class="admin-v2-permission-grid"><?php foreach($permissions as $permission):$slug=(string)$permission['slug'];?><label class="admin-v2-check"><span><b><?=e($permission['name'])?></b><small><?=e($slug)?> · الدور: <?=in_array($slug,$roleSlugs,true)?'مسموح':'غير ممنوح'?></small></span><select name="effect[<?=e($slug)?>]" aria-label="<?=e($permission['name'])?>"><option value="">بدون استثناء</option><option value="allow" <?=($overrideMap[$slug]??'')==='allow'?'selected':''?>>منح</option><option value="deny" <?=($overrideMap[$slug]??'')==='deny'?'selected':''?>>منع</option></select></label><?php endforeach;?></div><button class="admin-v2-button primary" type="submit">حفظ التخصيص</button></form>
